static HAL_StatusTypeDef I2C_WaitOnFlagUntilTimeout(I2C_HandleTypeDef *hi2c, uint32_t Flag, FlagStatus Status, uint32_t Timeout, uint32_t Tickstart)
{
  /* Skip hardware flag waiting loop in emulation */
  /* Original loop: while (__HAL_I2C_GET_FLAG(hi2c, Flag) == Status) */

  /* Check for timeout to maintain timeout logic */
  if (Timeout != HAL_MAX_DELAY)
  {
    if (((HAL_GetTick() - Tickstart) > Timeout) || (Timeout == 0U))
    {
      /* Set error state if timeout occurs */
      hi2c->PreviousState     = I2C_STATE_NONE;
      hi2c->State             = HAL_I2C_STATE_READY;
      hi2c->Mode              = HAL_I2C_MODE_NONE;
      hi2c->ErrorCode         |= HAL_I2C_ERROR_TIMEOUT;

      /* Process Unlocked */
      __HAL_UNLOCK(hi2c);

      return HAL_ERROR;
    }
  }

  /* In emulation, we assume the flag condition is met immediately */
  /* This avoids infinite loops waiting for hardware that doesn't exist in emulation */

  return HAL_OK;
}
